import sanitizeHtml from 'sanitize-html';

// Allowlist derived from inspecting the actual API-reference pages generated by
// docforge. Tags and attributes observed: <h2–h3> with id, <a> with href,
// <table>/<tr>/<th>/<td>, <ul>/<li>, <p>, <code>, <em>, <br />. No colspan,
// rowspan, class, or style attrs found. The list is intentionally minimal.
const SANITIZE_OPTIONS = {
  allowedTags: [
    'a', 'p', 'div', 'span',
    'ul', 'ol', 'li',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
    'code', 'pre', 'em', 'strong', 'b', 'i', 'br', 'hr',
    'table', 'thead', 'tbody', 'tr', 'th', 'td',
    'blockquote',
  ],
  allowedAttributes: {
    // id/name required for intra-page anchor targets (#section-name links).
    '*': ['id', 'name'],
    'a': ['href'],
    'td': ['colspan', 'rowspan'],
    'th': ['colspan', 'rowspan'],
  },
  allowedSchemes: ['http', 'https', 'mailto'],
  // Allow fragment-only hrefs (#anchor) in addition to the schemes above.
  allowedSchemesByTag: {
    'a': ['http', 'https', 'mailto', '#'],
  },
  // Discard any on* event handler that slips through attribute allowlist.
  disallowedTagsMode: 'discard',
  // sanitize-html does not set style/class; they are absent from our allowedAttributes.
};

/**
 * Sanitizes API HTML content then serialises it for safe embedding in a Vue
 * <script setup> block.
 *
 * Two layers of protection:
 *   1. sanitize-html removes event handlers, javascript: URLs, <script>/<style>/
 *      <iframe>/etc. and all non-allowlisted attributes (Fix 2 — client-side XSS).
 *   2. JSON.stringify → < escaping prevents the string from closing the
 *      surrounding SFC <script> block during SSR compilation (B2/B3).
 *
 * Returns the full <script setup> block text ready to prepend to the .md file.
 */
export function buildScriptSetup(htmlContent) {
  const clean = sanitizeHtml(htmlContent, SANITIZE_OPTIONS);
  const safeHtmlJson = JSON.stringify(clean).replace(/</g, '\\u003c');
  return `<script setup>\nconst apiHtml = ${safeHtmlJson};\n</script>\n\n`;
}
